Recursive approach - O(n) Time and O(n) SpaceThe idea is to check if the last two elements are in order, then recursively check the rest of the array. The base case is when the array has zero or one element, which is always considered sorted.Step-By-Step Approach:  If size of array is zero or one, return true. Check last two elements of array, if they are sorted, perform a recursive call with n-1  else, return false.
            C++

    #include <iostream>
#include <vector>
using namespace std;

// Helper function that takes array and size, used for recursion
bool isSortedHelper(vector<int>& arr, int n) {
    if (n == 0 || n == 1)
        return true;
    return arr[n - 1] >= arr[n - 2] && isSortedHelper(arr, n - 1);
}

// Main function to check if array is sorted, only takes array as input
bool isSorted(vector<int>& arr) {
    return isSortedHelper(arr, arr.size());
}

int main() {
    vector<int> arr = { 10, 20, 30, 40, 50 };
    cout << (isSorted(arr) ? "true\n" : "false\n");
    return 0;
}


